-- Generated by database/create_database.py

-- Source dates are stored as ISO YYYY-MM-DD text.

-- Monetary values use REAL for this analytics portfolio.

PRAGMA foreign_keys = ON;

CREATE TABLE "customers" (
    "customer_id" TEXT PRIMARY KEY NOT NULL,
    "customer_signup_date" TEXT NOT NULL,
    "gender" TEXT NOT NULL,
    "age" INTEGER,
    "age_group" TEXT NOT NULL,
    "state" TEXT NOT NULL,
    "city" TEXT NOT NULL,
    "pincode_prefix" INTEGER NOT NULL,
    "customer_segment" TEXT NOT NULL,
    "preferred_device" TEXT,
    "preferred_payment_method" TEXT NOT NULL,
    "acquisition_channel" TEXT NOT NULL,
    "total_orders" INTEGER NOT NULL,
    "total_spend" REAL NOT NULL,
    "average_order_value" REAL NOT NULL,
    "last_order_date" TEXT,
    "customer_status" TEXT NOT NULL,
    "loyalty_tier" TEXT NOT NULL
) STRICT;

CREATE TABLE "products" (
    "product_id" TEXT PRIMARY KEY NOT NULL,
    "product_name" TEXT NOT NULL,
    "category" TEXT NOT NULL,
    "subcategory" TEXT NOT NULL,
    "brand" TEXT NOT NULL,
    "price" REAL NOT NULL,
    "cost_price" REAL NOT NULL,
    "discount_range" TEXT NOT NULL,
    "rating_average" REAL,
    "rating_count" INTEGER NOT NULL,
    "stock_quantity" INTEGER NOT NULL,
    "product_launch_date" TEXT NOT NULL,
    "product_type" TEXT NOT NULL,
    "return_rate_baseline" REAL NOT NULL
) STRICT;

CREATE TABLE "marketing_campaigns" (
    "campaign_id" TEXT PRIMARY KEY NOT NULL,
    "campaign_name" TEXT NOT NULL,
    "channel" TEXT NOT NULL,
    "campaign_start_date" TEXT NOT NULL,
    "campaign_end_date" TEXT NOT NULL,
    "campaign_type" TEXT NOT NULL,
    "target_segment" TEXT NOT NULL,
    "discount_percentage" REAL NOT NULL,
    "impressions" INTEGER NOT NULL,
    "clicks" INTEGER NOT NULL,
    "conversions" INTEGER NOT NULL,
    "campaign_cost" REAL NOT NULL,
    "revenue_generated" REAL NOT NULL,
    "roi" REAL NOT NULL
) STRICT;

CREATE TABLE "orders" (
    "order_id" TEXT PRIMARY KEY NOT NULL,
    "customer_id" TEXT NOT NULL,
    "order_date" TEXT NOT NULL,
    "order_time" TEXT NOT NULL,
    "order_status" TEXT NOT NULL,
    "shipping_method" TEXT NOT NULL,
    "delivery_city" TEXT NOT NULL,
    "delivery_state" TEXT NOT NULL,
    "coupon_code" TEXT,
    "discount_percentage" REAL NOT NULL,
    "marketing_channel" TEXT NOT NULL,
    "subtotal" REAL NOT NULL,
    "shipping_fee" REAL NOT NULL,
    "tax_amount" REAL NOT NULL,
    "final_amount" REAL NOT NULL,
    "campaign_id" TEXT,
    FOREIGN KEY ("customer_id") REFERENCES "customers" ("customer_id"),
    FOREIGN KEY ("campaign_id") REFERENCES "marketing_campaigns" ("campaign_id")
) STRICT;

CREATE TABLE "order_items" (
    "order_item_id" TEXT PRIMARY KEY NOT NULL,
    "order_id" TEXT NOT NULL,
    "product_id" TEXT NOT NULL,
    "quantity" INTEGER NOT NULL,
    "unit_price" REAL NOT NULL,
    "discount_percentage" REAL NOT NULL,
    "item_revenue" REAL NOT NULL,
    "item_cost" REAL NOT NULL,
    "profit" REAL NOT NULL,
    FOREIGN KEY ("order_id") REFERENCES "orders" ("order_id"),
    FOREIGN KEY ("product_id") REFERENCES "products" ("product_id")
) STRICT;

CREATE TABLE "payments" (
    "payment_id" TEXT PRIMARY KEY NOT NULL,
    "order_id" TEXT NOT NULL,
    "payment_date" TEXT NOT NULL,
    "payment_method" TEXT NOT NULL,
    "payment_status" TEXT NOT NULL,
    "amount_paid" REAL NOT NULL,
    "transaction_fee" REAL NOT NULL,
    "refund_amount" REAL NOT NULL,
    FOREIGN KEY ("order_id") REFERENCES "orders" ("order_id"),
    UNIQUE ("order_id")
) STRICT;

CREATE TABLE "shipments" (
    "shipment_id" TEXT PRIMARY KEY NOT NULL,
    "order_id" TEXT NOT NULL,
    "warehouse_city" TEXT NOT NULL,
    "delivery_city" TEXT NOT NULL,
    "shipping_method" TEXT NOT NULL,
    "dispatch_date" TEXT NOT NULL,
    "expected_delivery_date" TEXT NOT NULL,
    "actual_delivery_date" TEXT,
    "delivery_days" REAL,
    "delivery_status" TEXT NOT NULL,
    "delayed_flag" INTEGER NOT NULL,
    "delivery_days_calculated" INTEGER,
    "delivery_days_mismatch" INTEGER NOT NULL CHECK ("delivery_days_mismatch" IN (0, 1)),
    "possible_year_end_clipping" INTEGER NOT NULL CHECK ("possible_year_end_clipping" IN (0, 1)),
    FOREIGN KEY ("order_id") REFERENCES "orders" ("order_id"),
    UNIQUE ("order_id")
) STRICT;

CREATE TABLE "returns" (
    "return_id" TEXT PRIMARY KEY NOT NULL,
    "order_id" TEXT NOT NULL,
    "customer_id" TEXT NOT NULL,
    "product_id" TEXT NOT NULL,
    "return_date" TEXT NOT NULL,
    "return_reason" TEXT NOT NULL,
    "refund_amount" REAL NOT NULL,
    "return_status" TEXT NOT NULL,
    FOREIGN KEY ("order_id") REFERENCES "orders" ("order_id"),
    FOREIGN KEY ("customer_id") REFERENCES "customers" ("customer_id"),
    FOREIGN KEY ("product_id") REFERENCES "products" ("product_id")
) STRICT;

CREATE TABLE "customer_reviews" (
    "review_id" TEXT PRIMARY KEY NOT NULL,
    "order_id" TEXT NOT NULL,
    "customer_id" TEXT NOT NULL,
    "product_id" TEXT NOT NULL,
    "review_date" TEXT NOT NULL,
    "rating" INTEGER NOT NULL,
    "review_sentiment" TEXT,
    "verified_purchase" INTEGER NOT NULL CHECK ("verified_purchase" IN (0, 1)),
    FOREIGN KEY ("order_id") REFERENCES "orders" ("order_id"),
    FOREIGN KEY ("customer_id") REFERENCES "customers" ("customer_id"),
    FOREIGN KEY ("product_id") REFERENCES "products" ("product_id")
) STRICT;
